tool_args.old_string:
\paragraph{Architecture.}
\looseness=-1 The CRM consists of three fully connected layers with ReLU activations: $\mathrm{Linear}(n_{\mathrm{in}}, 256) \to \mathrm{ReLU} \to \mathrm{Linear}(256, 256) \to \mathrm{ReLU} \to \mathrm{Linear}(256, 30)$, preceded by input normalization. For the primary obs\_only variant ($n_{\mathrm{in}}{=}990$), the input is the concatenation of the frozen observation embedding $\mathbf{z}_{\mathrm{obs}} \in \mathbb{R}^{960}$ from SmolVLA's vision-language encoder and the selected action $a_{\mathrm{base}} \in \mathbb{R}^{30}$ ($H{=}5$ steps $\times$ $d{=}6$ DOFs), for a total of 327,198 parameters (${\sim}$327K). The output is a residual $\boldsymbol{\delta} \in \mathbb{R}^{30}$, and the corrected action is:
\begin{equation}
  \mathbf{a}^* = a_{\mathrm{base}} + \mathrm{clip}\bigl(\boldsymbol{\delta},\; \|\boldsymbol{\delta}\|_2 \leq \varepsilon\bigr),
  \label{eq:crm}
\end{equation}
where $\varepsilon$ is a norm bound that limits the correction magnitude (Section~\ref{sec:magnitude}). The CRM never sees individual action candidates: it receives only the already-selected $a_{\mathrm{base}}$ and predicts a correction toward the expert action.

\paragraph{Conditioning variants.}
We compare three CRM variants that share the same MLP architecture but differ in their input:
\begin{itemize}[nosep]
  \item \textbf{obs\_only} (primary): $[\mathbf{z}_{\mathrm{obs}};\, a_{\mathrm{base}}] \in \mathbb{R}^{990}$, 327K parameters. No conformal or uncertainty features.
  \item \textbf{perdof}: $[\mathbf{z}_{\mathrm{obs}};\, a_{\mathrm{base}};\, \mathbf{u}_{\mathrm{dof}}] \in \mathbb{R}^{1030}$, 337K parameters. $\mathbf{u}_{\mathrm{dof}}$ concatenates per-DOF standard deviations, conformal prediction radii~\cite{angelopoulos2023gentle}, and covariance log-volumes~\cite{ledoit2004well} ($40$D total).
  \item \textbf{scalar}: $[\mathbf{z}_{\mathrm{obs}};\, a_{\mathrm{base}};\, u_s] \in \mathbb{R}^{991}$, 327K parameters, where $u_s$ is a single scalar uncertainty summary.
\end{itemize}
Section~\ref{sec:magnitude_results} shows that conformal features fail to improve closed-loop performance; obs\_only is our primary method.

tool_args.new_string:
\paragraph{Architecture.}
\looseness=-1 The CRM consists of three fully connected layers with ReLU activations: $\mathrm{Linear}(n_{\mathrm{in}}, 256) \to \mathrm{ReLU} \to \mathrm{Linear}(256, 256) \to \mathrm{ReLU} \to \mathrm{Linear}(256, H{\cdot}d)$, preceded by input normalization. The input is the concatenation of the frozen observation embedding $\mathbf{z}_{\mathrm{obs}} \in \mathbb{R}^{n_{\mathrm{obs}}}$ from the VLA's vision-language encoder and the selected action $a_{\mathrm{base}} \in \mathbb{R}^{H \cdot d}$ ($H{=}5$ steps $\times$ $d{=}6$ DOFs), giving $n_{\mathrm{in}} = n_{\mathrm{obs}} + 30$. The architecture is identical across VLAs; only $n_{\mathrm{obs}}$ differs ($960$ for SmolVLA, $2048$ for $\pi_{0.5}$), yielding $327$K--$615$K parameters ($<\!1$\% of either backbone). The output is a residual $\boldsymbol{\delta} \in \mathbb{R}^{30}$, and the corrected action is:
\begin{equation}
  \mathbf{a}^* = a_{\mathrm{base}} + \mathrm{clip}\bigl(\boldsymbol{\delta},\; \|\boldsymbol{\delta}\|_2 \leq \varepsilon\bigr),
  \label{eq:crm}
\end{equation}
where $\varepsilon$ is a norm bound that limits the correction magnitude (Section~\ref{sec:magnitude}). The CRM never sees individual action candidates: it receives only the already-selected $a_{\mathrm{base}}$ and predicts a correction toward the expert action. We ablate alternative conditioning inputs (per-DOF conformal features, scalar uncertainty) in Section~\ref{sec:magnitude_results}; observation-only conditioning is the primary and best-performing variant.

tool_args.old_string:
\paragraph{Training.}
\looseness=-1 The CRM is trained offline on demonstration trajectories from LIBERO~\cite{liu2023libero} with $L_2$ loss:
\begin{equation}
  \mathcal{L} = \bigl\|\mathbf{a}^* - \mathbf{a}_{\mathrm{expert}}\bigr\|_2^2,
  \label{eq:loss}
\end{equation}
where $\mathbf{a}_{\mathrm{expert}}$ is the demonstration action. The training set comprises 26{,}737 precomputed samples from 10 demonstrations per task across 20 LIBERO tasks. For each demonstration step, we run $K{=}10$ forward passes through the frozen SmolVLA, apply argmin selection~(\ref{eq:argmin}) to obtain $a_{\mathrm{base}}$, and train the CRM to predict the residual toward $\mathbf{a}_{\mathrm{expert}}$. Data augmentation (Gaussian noise on $a_{\mathrm{base}}$ and uncertainty features) improves generalization to the closed-loop state distribution~\cite{ross2011dagger}.

tool_args.new_string:
\paragraph{Training.}
\looseness=-1 The CRM is trained offline on demonstration trajectories from LIBERO~\cite{liu2023libero} with $L_2$ loss:
\begin{equation}
  \mathcal{L} = \bigl\|\mathbf{a}^* - \mathbf{a}_{\mathrm{expert}}\bigr\|_2^2,
  \label{eq:loss}
\end{equation}
where $\mathbf{a}_{\mathrm{expert}}$ is the demonstration action. For each VLA, we precompute training data from 10 demonstrations per task across all 40 LIBERO tasks (4 suites). At each demonstration step, we run $K{=}10$ forward passes through the frozen VLA, apply argmin selection~(\ref{eq:argmin}) to obtain $a_{\mathrm{base}}$, and train the CRM to predict the residual toward $\mathbf{a}_{\mathrm{expert}}$. Training uses Adam ($\mathrm{lr}{=}10^{-3}$), batch size 32, 50 epochs, with Gaussian noise augmentation on $a_{\mathrm{base}}$ to improve generalization to the closed-loop state distribution~\cite{ross2011dagger}.
